import openpyxl
from openpyxl.utils import get_column_letter

path='/root/output/result.xlsx'
wb=openpyxl.load_workbook(path)
ws=wb['Task']

# Verify no extra sheets
assert wb.sheetnames==['Task','Data'], wb.sheetnames

cols=range(8,13) # H-L

def is_formula(v):
    return isinstance(v,str) and v.startswith('=')

checks=[]
# lookup ranges
for (r1,r2) in [(12,17),(19,24),(26,31)]:
    for r in range(r1,r2+1):
        for c in cols:
            addr=f'{get_column_letter(c)}{r}'
            checks.append(('lookup',addr,is_formula(ws[addr].value)))

for r in range(35,41):
    for c in cols:
        addr=f'{get_column_letter(c)}{r}'
        checks.append(('net',addr,is_formula(ws[addr].value)))

for r in range(42,48):
    for c in cols:
        addr=f'{get_column_letter(c)}{r}'
        checks.append(('stats',addr,is_formula(ws[addr].value)))

for c in cols:
    addr=f'{get_column_letter(c)}50'
    checks.append(('weighted',addr,is_formula(ws[addr].value)))

bad=[t for t in checks if not t[2]]
print('Total checked:', len(checks))
print('Missing formulas:', len(bad))
if bad:
    print('First few:', bad[:10])

# Spot-check fills unchanged: verify target cells still yellow (FFF2CC)
for addr in ['H12','L17','H24','H31','H35','H42','H50']:
    rgb=ws[addr].fill.start_color.rgb
    print('Fill', addr, rgb)

